#!/usr/bin/env node
// Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
// PreToolUse-equivalent guards for OpenCode V2.
//
// The Python modules are owned by my-claude-stuff and shared with Claude Code
// and Codex. This file only translates OpenCode tool names and input shapes
// into the payloads those modules read, then blocks on exit 2.
//
// Fail-closed: a missing interpreter or importable module rejects the action
// with the exact error. The model sees the rejection and must choose a path
// that does not rely on a broken guard.

import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";

const BLOCKED_EXIT = 2;
const TIMEOUT_MS = 5000;
const COMMAND_TOOLS = new Set(["shell", "bash", "exec", "execute"]);
const PATH_KEYS = [
  "filePath",
  "file_path",
  "filepath",
  "path",
  "paths",
  "filePaths",
  "pattern",
];

// block_paths reads a different input field per tool name. Sending file_path
// under Grep/Glob makes those checks no-ops.
const TOOL_PATH_FIELDS = { Grep: "path", Glob: "pattern" };
const ACTION_TOOLS = { grep: "Grep", glob: "Glob" };

// Chained segments bypass the shell allows' command word. These are the
// highest-value dump primitives; the shared guard has no rule for them.
const ENV_DUMP_COMMANDS = new Set(["env", "printenv", "set"]);
const TRAVERSAL_ROOTS = [
  "/.claude/skills/",
  "/source/gws-cli-notes/scripts/",
  "/source/cited-research/scripts/",
  "/.local/share/cited-research-data/",
];

export const TOOL_NAMES = {
  read: "Read",
  write: "Write",
  edit: "Edit",
  grep: "Grep",
  glob: "Glob",
  shell: "Bash",
};

const warnedModules = new Set();

// Test hook: warnings are deduped per module for the life of the process, so
// tests that assert on the warning count must start from a clean set.
export function clearWarnedModules() {
  warnedModules.clear();
}

class GuardUnavailable extends Error {}

export function pythonCommand() {
  const raw = (process.env.OPENCODE_GUARD_PYTHON || "python3").trim();
  const parts = [];
  let current = "";
  let quote = null;
  for (const char of raw) {
    if (quote) {
      if (char === quote) quote = null;
      else current += char;
    } else if (char === '"' || char === "'") {
      quote = char;
    } else if (/\s/.test(char)) {
      if (current) {
        parts.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }
  if (current) parts.push(current);
  const [command, ...args] = parts.length ? parts : ["python3"];
  return { command, args };
}

export function commandPayload(command) {
  return { tool_name: "Bash", tool_input: { command } };
}

export function pathPayload(filePath, cwd, toolName = "Read") {
  const field = TOOL_PATH_FIELDS[toolName] || "file_path";
  return { tool_name: toolName, tool_input: { [field]: filePath }, cwd };
}

export function inputPaths(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) return [];
  const paths = [];
  for (const key of PATH_KEYS) {
    const value = input[key];
    if (typeof value === "string") paths.push(value);
    if (Array.isArray(value)) {
      paths.push(...value.filter((item) => typeof item === "string"));
    }
  }
  return [...new Set(paths)];
}

export function patchPaths(patchText) {
  if (typeof patchText !== "string") return [];
  const paths = new Set();
  for (const match of patchText.matchAll(
    /^\*\*\*\s+(?:Add File|Update File|Delete File|Move to):\s*(.+?)\s*$/gm,
  )) {
    paths.add(match[1]);
  }
  for (const match of patchText.matchAll(/^(?:---|\+\+\+)\s+(?:[ab]\/)?(.+?)\s*$/gm)) {
    if (match[1] !== "/dev/null") paths.add(match[1]);
  }
  return [...paths];
}

export function toolPayloads(tool, input, cwd) {
  const payloads = [];
  const record =
    input && typeof input === "object" && !Array.isArray(input) ? input : {};

  if (COMMAND_TOOLS.has(tool) && typeof record.command === "string") {
    payloads.push(commandPayload(record.command));
  }
  if (tool === "patch") {
    for (const filePath of patchPaths(record.patchText)) {
      payloads.push(pathPayload(filePath, cwd, "Edit"));
    }
  }
  if (tool === "webfetch" && typeof record.url === "string") {
    payloads.push({ tool_name: "WebFetch", tool_input: { url: record.url }, cwd });
  }
  for (const filePath of inputPaths(record)) {
    payloads.push(pathPayload(filePath, cwd, TOOL_NAMES[tool] || "Read"));
  }
  return payloads;
}

export function permissionPayloads(action, resources, cwd) {
  if (!Array.isArray(resources)) return [];
  const payloads = [];
  if (action === "shell") {
    for (const resource of resources) {
      if (typeof resource === "string") payloads.push(commandPayload(resource));
    }
  }
  if (
    ["read", "edit", "write", "grep", "glob", "external_directory"].includes(
      action,
    )
  ) {
    for (const resource of resources) {
      if (typeof resource === "string") {
        payloads.push(
          pathPayload(resource, cwd, ACTION_TOOLS[action] || "Read"),
        );
      }
    }
  }
  return payloads;
}

// --- Per-segment permission evaluation -------------------------------------
// Claude's permission layer evaluates each command in a chain. OpenCode globs
// match the whole string, so `git status && <anything>` matched the allow.
// Split the chain and resolve each segment against the deployed rules.

const warnedRules = new Set();

export function loadRules(configPath) {
  try {
    const data = JSON.parse(readFileSync(configPath, "utf8"));
    return {
      permissions: Array.isArray(data.permissions) ? data.permissions : [],
      policies: Array.isArray(data.policies) ? data.policies : [],
    };
  } catch (error) {
    if (!warnedRules.has(configPath)) {
      warnedRules.add(configPath);
      console.error(
        `[harness-guards] permission rules unavailable at ${configPath}: ${error.message}`,
      );
    }
    return { permissions: [], policies: [] };
  }
}

export function clearWarnedRules() {
  warnedRules.clear();
}

function globBody(pattern) {
  return [...pattern]
    .map((char) =>
      char === "*"
        ? ".*"
        : char === "?"
          ? "."
          : char.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
    )
    .join("");
}

export function globMatches(pattern, value) {
  const body = pattern.endsWith(" *")
    ? `${globBody(pattern.slice(0, -2))}( .*)?`
    : globBody(pattern);
  return new RegExp(`^${body}$`, "s").test(value);
}

export function splitSegments(command) {
  const segments = [];
  let current = "";
  let quote = null;
  for (let index = 0; index < command.length; index += 1) {
    const char = command[index];
    if (quote) {
      if (char === quote) quote = null;
      current += char;
      continue;
    }
    if (char === "'" || char === '"') {
      quote = char;
      current += char;
      continue;
    }
    if ((char === "&" || char === "|") && command[index + 1] === char) {
      segments.push(current);
      current = "";
      index += 1;
      continue;
    }
    if (char === "|" || char === ";") {
      segments.push(current);
      current = "";
      continue;
    }
    current += char;
  }
  segments.push(current);
  return segments.map((segment) => segment.trim()).filter(Boolean);
}

// ponytail: non-nested substitution only; a nested `$()` is still evaluated as
// part of its outer segment. Upgrade to a real parser if that matters.
export function substitutions(text) {
  const found = [];
  for (const pattern of [/\$\(([^()]*)\)/g, /`([^`]*)`/g]) {
    for (const match of text.matchAll(pattern)) found.push(match[1]);
  }
  return found;
}

export function resolvePermissionRule(rules, action, resource) {
  let effect = null;
  for (const rule of rules) {
    if (rule.action !== "*" && rule.action !== action) continue;
    if (globMatches(rule.resource, resource)) effect = rule.effect;
  }
  return effect;
}

export function resolvePolicyRule(policies, resource) {
  let effect = "allow";
  for (const policy of policies) {
    if (policy.action !== "tool.use") continue;
    if (globMatches(policy.resource, resource)) effect = policy.effect;
  }
  return effect;
}

export function chainVerdicts(command, rules, policies) {
  const deny = [];
  const ask = [];
  if (!Array.isArray(rules) || rules.length === 0) return { deny, ask };
  const visit = (text) => {
    for (const segment of splitSegments(text)) {
      const denied =
        resolvePolicyRule(policies, `shell:${segment}`) === "deny" ||
        resolvePermissionRule(rules, "shell", segment) === "deny";
      if (denied) deny.push(segment);
      else if (resolvePermissionRule(rules, "shell", segment) !== "allow") {
        ask.push(segment);
      }
      for (const inner of substitutions(segment)) visit(inner);
    }
  };
  visit(command);
  return {
    deny: [...new Set(deny)],
    ask: [...new Set(ask)].filter((segment) => !deny.includes(segment)),
  };
}

export function shellProblem(command) {
  if (typeof command !== "string") return null;
  if (command.includes("<<")) {
    return "heredoc is not allowed; it hides chained commands";
  }
  if (command.includes("<(")) {
    return "process substitution is not allowed";
  }
  for (const segment of command.split(/&&|\|\||[|;]/)) {
    const first = segment.trim().split(/\s+/)[0] || "";
    if (ENV_DUMP_COMMANDS.has(first)) {
      return `environment dump (${first}) is not allowed`;
    }
  }
  for (const token of command.split(/\s+/)) {
    const cleaned = token.replace(/^['"]|['"]$/g, "");
    if (
      cleaned.includes("..") &&
      TRAVERSAL_ROOTS.some((root) => cleaned.includes(root))
    ) {
      return `path traversal in an allowlisted skill path: ${cleaned}`;
    }
  }
  return null;
}

export function run(module, payload) {
  const { command, args } = pythonCommand();
  const result = spawnSync(command, [...args, "-m", module], {
    input: JSON.stringify(payload),
    encoding: "utf8",
    timeout: TIMEOUT_MS,
    maxBuffer: 1024 * 1024,
    // `python -m` puts the working directory first on sys.path. Spawn from a
    // neutral directory and disable the implicit cwd entry so a
    // project-local harness_guards cannot shadow the installed guard.
    cwd: tmpdir(),
    env: { ...process.env, PYTHONSAFEPATH: "1" },
  });

  if (result.status === BLOCKED_EXIT) {
    return (result.stderr || `Blocked by ${module}`).trim();
  }
  if (result.error || result.status !== 0) {
    const detail =
      result.error?.message || result.stderr || `exit ${result.status}`;
    if (!warnedModules.has(module)) {
      warnedModules.add(module);
      console.error(`[harness-guards] ${module} unavailable: ${detail}`);
    }
    throw new GuardUnavailable(`${module} unavailable: ${detail}`);
  }
  return null;
}

function checkPayloads(payloads, cwd) {
  for (const payload of payloads) {
    if (typeof payload.tool_input?.command === "string") {
      const problem = shellProblem(payload.tool_input.command);
      if (problem) return `BLOCKED: ${problem}`;
      const message = run("harness_guards.block_commands", payload);
      if (message) return message;
    }
    const pathCheck = payload.cwd || !cwd ? payload : { ...payload, cwd };
    const message = run("harness_guards.block_paths", pathCheck);
    if (message) return message;
  }
  return null;
}

export function checkTool(tool, input, cwd) {
  return checkPayloads(toolPayloads(tool, input, cwd), cwd);
}

export function checkPermission(action, resources, cwd) {
  return checkPayloads(permissionPayloads(action, resources, cwd), cwd);
}

function blockedMessage(error) {
  if (!(error instanceof GuardUnavailable)) throw error;
  return `BLOCKED: ${error.message}. Refusing to run unguarded; fix harness_guards or set OPENCODE_GUARD_PYTHON.`;
}

const plugin = {
  id: "harness-guards",
  async setup(ctx) {
    const cwd = ctx?.location?.directory || process.cwd();
    const configDir =
      process.env.OPENCODE_DIR || join(homedir(), ".config", "opencode");
    const rules = loadRules(join(configDir, "opencode.json"));

    await ctx.tool.hook("execute.before", (event) => {
      try {
        const message = checkTool(event.tool, event.input, cwd);
        if (message) throw new Error(message);
        if (
          COMMAND_TOOLS.has(event.tool) &&
          typeof event.input?.command === "string"
        ) {
          const verdict = chainVerdicts(
            event.input.command,
            rules.permissions,
            rules.policies,
          );
          if (verdict.deny.length) {
            throw new Error(
              `BLOCKED: chained segment denied: ${verdict.deny[0]}`,
            );
          }
        }
      } catch (error) {
        throw new Error(blockedMessage(error));
      }
    });

    await ctx.permission.hook("evaluate", (event) => {
      try {
        const message = checkPermission(event.action, event.resources, cwd);
        if (message) {
          event.effect = "deny";
          event.message = message;
          return;
        }
        if (event.action !== "shell" || !Array.isArray(event.resources)) return;
        for (const resource of event.resources) {
          if (typeof resource !== "string") continue;
          const verdict = chainVerdicts(
            resource,
            rules.permissions,
            rules.policies,
          );
          if (verdict.deny.length) {
            event.effect = "deny";
            event.message = `BLOCKED: chained segment denied: ${verdict.deny[0]}`;
            return;
          }
          if (verdict.ask.length && event.effect === "allow") {
            event.effect = "ask";
            event.message = `Approval required for chained segment: ${verdict.ask[0]}`;
          }
        }
      } catch (error) {
        event.effect = "deny";
        event.message = blockedMessage(error);
      }
    });
  },
};

export default plugin;
